<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/crypto.php';$merchant=require_login();$pageTitle='Integrations';$pdo=db();$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$label=trim((string)($_POST['account_label']??'Primary UPI'));$upi=trim((string)($_POST['upi_id']??''));$email=filter_var($_POST['linked_email']??'',FILTER_VALIDATE_EMAIL);$pass=preg_replace('/\s+/','',(string)($_POST['app_password']??''));if(!$email||!preg_match('/^[A-Za-z0-9._-]{2,128}@[A-Za-z0-9.-]{3,190}$/',$upi)||($pass!==''&&!preg_match('/^[A-Za-z0-9]{16}$/',$pass))){$notice='Enter a valid email, UPI ID, and (if updating) a 16-character app password.';}else{try{$existing=$pdo->prepare('SELECT id FROM merchant_accounts WHERE merchant_id=? ORDER BY id LIMIT 1');$existing->execute([$merchant['id']]);$row=$existing->fetch();if($row){if($pass!=='')$pdo->prepare('UPDATE merchant_accounts SET account_label=?,upi_id=?,linked_email=?,google_app_password=? WHERE id=? AND merchant_id=?')->execute([$label,$upi,$email,encrypt_secret($pass),$row['id'],$merchant['id']]);else $pdo->prepare('UPDATE merchant_accounts SET account_label=?,upi_id=?,linked_email=? WHERE id=? AND merchant_id=?')->execute([$label,$upi,$email,$row['id'],$merchant['id']]);}else{if($pass==='')throw new RuntimeException('An app password is required for the first connection.');$pdo->prepare('INSERT INTO merchant_accounts(merchant_id,account_label,upi_id,linked_email,google_app_password) VALUES(?,?,?,?,?)')->execute([$merchant['id'],$label,$upi,$email,encrypt_secret($pass)]);}$notice='Integration settings saved. Configure the private IMAP cron before accepting production payments.';}catch(Throwable $e){error_log('Integration settings save failed: '.$e->getMessage());$notice='Could not save settings. Confirm encryption key and database configuration.';}}}$q=$pdo->prepare('SELECT account_label,upi_id,linked_email,is_active,last_checked_at FROM merchant_accounts WHERE merchant_id=? ORDER BY id LIMIT 1');$q->execute([$merchant['id']]);$account=$q->fetch()?:[];require __DIR__.'/includes/dashboard-header.php';?>
<div class="page-title"><div><h1>Integrations</h1><p>Configure your receiving UPI account and an opt-in receipt mailbox.</p></div></div><div class="note">Use a dedicated email inbox with only the access needed for payment receipts. The app password grants mailbox access, not just receipt access. It is encrypted at rest, but it remains a sensitive credential. Revoke it when no longer required; review applicable privacy and provider terms.</div><div class="card panel"><div class="card-title"><h3>UPI account & receipt mailbox</h3><span class="badge <?=($account['is_active']??false)?'badge-success':'badge-pending'?>"><?=($account['is_active']??false)?'Connected':'Not configured'?></span></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="field"><label>Account label</label><input name="account_label" value="<?=h($account['account_label']??'Primary UPI')?>" required></div><div class="field"><label>UPI ID</label><input name="upi_id" value="<?=h($account['upi_id']??'')?>" placeholder="name@bank" required></div><div class="field"><label>Receipt email address</label><input type="email" name="linked_email" value="<?=h($account['linked_email']??'')?>" required></div><div class="field"><label>Google app password <?=!empty($account)?'(leave blank to keep current)':''?></label><input type="password" name="app_password" pattern="[A-Za-z0-9 ]{16,20}" autocomplete="new-password" <?=empty($account)?'required':''?> placeholder="16 characters"></div><div class="field full"><button class="btn">Save integration</button></div></form><?php if($account):?><p style="font-size:10px;color:#758299">Last parser check: <?=h($account['last_checked_at']?:'Not checked yet')?></p><?php endif?></div>
<div class="card panel"><div class="card-title"><h3>How to create a Google app password</h3><button class="btn btn-outline" onclick="document.getElementById('app-guide').hidden=!document.getElementById('app-guide').hidden">View instructions</button></div><div id="app-guide" hidden><ol style="font-size:11px;line-height:2;color:#5f6c81"><li>Enable two-step verification on the dedicated mailbox account.</li><li>Visit the Google Account security settings and find App passwords (availability may vary by account).</li><li>Create a password for this deployment and copy it once into the encrypted field above.</li><li>Enable IMAP for that mailbox, configure the cron privately, test with a receipt sample, and revoke the app password if you disconnect.</li></ol><div class="note">Never paste this password into chat, logs, source control or browser code. Receipt parsing is provider-format-specific and should be tested against non-sensitive samples.</div></div></div><?php require __DIR__.'/includes/dashboard-footer.php';?>